// Cloudflare entry point: canonical redirects first, then the OpenNext site.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore -- generated by `npm run build`, absent on a fresh checkout
import site from "./.open-next/worker.js";
import { canonicalRedirect } from "./canonical-redirect";
import { deleteExpiredInquiries } from "./retention";

interface ScheduledContext { waitUntil(promise: Promise<unknown>): void }

const worker = {
  fetch(request: Request, env: unknown, ctx: unknown) {
    return canonicalRedirect(request) ?? site.fetch(request, env, ctx);
  },
  // Daily, from the cron trigger in wrangler.jsonc.
  scheduled(_event: unknown, env: { SUPABASE_URL?: string; SUPABASE_SECRET_KEY?: string }, ctx: ScheduledContext) {
    ctx.waitUntil(deleteExpiredInquiries(env));
  },
};

export default worker;
